<?php namespace App\Filament\Resources\ArticleResource\Pages; use App\Filament\Pages\CreateAuditedRecord; use App\Filament\Resources\ArticleResource; use App\Services\ContentSanitizer; class CreateArticle extends CreateAuditedRecord {protected static string $resource=ArticleResource::class; protected function mutateFormDataBeforeCreate(array $data):array{$data['legacy_wp_id']=random_int(1000000000,2000000000);$data['original_title']=$data['title'];$data['legacy_url']='/'.$data['slug'];$data['content_html']=app(ContentSanitizer::class)->sanitize($data['content_html']??'')['html'];if(($data['status']??null)==='published'&&!($data['published_at']??null))$data['published_at']=now();return $data;}}
